import test from 'node:test';import assert from 'node:assert/strict';import{realpath,mkdtemp,cp,readFile,writeFile,rm,mkdir}from'node:fs/promises';import{tmpdir}from'node:os';import{resolve,join,dirname}from'node:path';import{fileURLToPath}from'node:url';import{runVoiceAdmission}from'./voice-admission.mjs';
const production=dirname(fileURLToPath(import.meta.url)),id='reel-article-porto-3-jours-sans-voiture',batchId='instagram-porto-voix-2026-11-01-v1';
const now=()=>Date.parse('2026-10-12T09:00:00Z');
async function fixture(t,remove=false){const root=await realpath(await mkdtemp(join(tmpdir(),'vsd-admit-')));t.after(()=>rm(root,{recursive:true,force:true}));const p=join(root,'.github/vsd-production');await mkdir(p,{recursive:true});await cp(join(production,'reviewed-social'),join(p,'reviewed-social'),{recursive:true});await cp(join(production,'voice-revisions/clear-v1',id),join(p,'voice-stock',id),{recursive:true});const file=join(p,'reviewed-social',batchId+'.json');const batch=JSON.parse(await readFile(file,'utf8'));if(remove){const ip=join(p,'reviewed-social/index.json'),index=JSON.parse(await readFile(ip,'utf8'));index.items=index.items.filter(x=>x.batchId!==batchId);await writeFile(ip,JSON.stringify(index));await rm(file);}return{root,p,batch};}
test('existing content is skipped without preparing or sending a duplicate',async t=>{const f=await fixture(t);const result=await runVoiceAdmission({repositoryRoot:f.root,now,build:()=>assert.fail('duplicate')});assert.equal(result.changed,false);assert.equal(result.skipped.length,1);});
test('one prepared lot is indexed once and next pass is idle',async t=>{const f=await fixture(t,true);let calls=0;const result=await runVoiceAdmission({repositoryRoot:f.root,now,build:({occupied})=>{calls++;assert.ok(occupied.length>0);return{status:'batch_prepared_not_imported',batch:f.batch};}});assert.equal(result.changed,true);assert.equal(result.publicationAttempted,false);assert.equal(calls,1);assert.equal((await runVoiceAdmission({repositoryRoot:f.root,now,build:()=>assert.fail('repeated')})).changed,false);});
test('an expired or conflicting lot cannot be indexed',async t=>{const f=await fixture(t,true);f.batch.items[0].review.validUntil='2026-10-11T00:00:00Z';await assert.rejects(runVoiceAdmission({repositoryRoot:f.root,now,build:()=>({status:'batch_prepared_not_imported',batch:f.batch})}),/expired_batch/);});
test('same identity with different bytes is held',async t=>{const f=await fixture(t);const p=join(f.p,'voice-stock',id,'selection.json'),s=JSON.parse(await readFile(p,'utf8'));s.mediaSha256='0'.repeat(64);await writeFile(p,JSON.stringify(s));await assert.rejects(runVoiceAdmission({repositoryRoot:f.root,now}),/existing_content_conflict/);});
test('annual stop precedes disk access',async()=>assert.equal((await runVoiceAdmission({repositoryRoot:'/absent',now:()=>Date.parse('2027-09-15T00:00:00Z')})).status,'period_ended'));
